"""Validate the pinned source-patched runtime before preparing Android assets."""
import json
import shutil
from ruffle_archive import ROOT, patched_archive, verify_runtime


def main():
    files, metadata = verify_runtime(patched_archive())
    destination = ROOT / "app/build/generated/ruffleAssets/ruffle"
    # This directory is exclusively generated by this task. Remove stale chunks.
    if not destination.resolve().is_relative_to((ROOT / "app/build").resolve()):
        raise RuntimeError("Generated extension directory escapes the build directory")
    if destination.exists():
        shutil.rmtree(destination)
    for name, data in files.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    (destination.parent / "ruffle-build.json").write_text(json.dumps(metadata), encoding="utf-8")
    print(f"Verified Ruffle {metadata['version']}, extension {metadata['manifestVersion']}")


if __name__ == "__main__":
    main()
